window.LEX_LIBRARY.questions.push(...[{"id": "lawtext-B0000001-791-2", "subject": "物權", "topic": "權利主體・§791", "kind": "法條", "question": "【法條原文辨識】依《民法》第791條，下列節錄的【空格】應填入何者？\n\n「前項情形，土地【空格】受有損害者，得請求賠償。於未受賠償前，得留置其物品或動物。」", "options": ["承租人", "所有人", "共有人", "占有人"], "answer": 1, "explanations": ["此處不是「承租人」。民法第791條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第791條此處原文是「所有人」。\n原句：前項情形，土地所有人受有損害者，得請求賠償。於未受賠償前，得留置其物品或動物。", "此處不是「共有人」。民法第791條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「占有人」。民法第791條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第791條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=791", "text": "土地所有人，遇他人之物品或動物偶至其地內者，應許該物品或動物之占有人或所有人入其地內，尋查取回。\n前項情形，土地所有人受有損害者，得請求賠償。於未受賠償前，得留置其物品或動物。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-836-1-1", "subject": "物權", "topic": "權利主體・§836-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第836-1條，下列節錄的【空格】應填入何者？\n\n「土地所有權讓與時，已預付之地租，非經登記，不得對抗【空格】。」", "options": ["受益人", "第三人", "債權人", "債務人"], "answer": 1, "explanations": ["此處不是「受益人」。民法第836-1條在本題位置規定的是「第三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第836-1條此處原文是「第三人」。\n原句：土地所有權讓與時，已預付之地租，非經登記，不得對抗第三人。", "此處不是「債權人」。民法第836-1條在本題位置規定的是「第三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「債務人」。民法第836-1條在本題位置規定的是「第三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第836-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=836-1", "text": "土地所有權讓與時，已預付之地租，非經登記，不得對抗第三人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-873-1", "subject": "物權", "topic": "物權種類・§873", "kind": "法條", "question": "【法條原文辨識】依《民法》第873條，下列節錄的【空格】應填入何者？\n\n「【空格】人，於債權已屆清償期，而未受清償者，得聲請法院，拍賣抵押物，就其賣得價金而受清償。」", "options": ["所有權", "典權", "地上權", "抵押權"], "answer": 3, "explanations": ["此處不是「所有權」。民法第873條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「典權」。民法第873條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「地上權」。民法第873條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第873條此處原文是「抵押權」。\n原句：抵押權人，於債權已屆清償期，而未受清償者，得聲請法院，拍賣抵押物，就其賣得價金而受清償。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第873條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=873", "text": "抵押權人，於債權已屆清償期，而未受清償者，得聲請法院，拍賣抵押物，就其賣得價金而受清償。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-796-1-1", "subject": "物權", "topic": "犯罪與責任・§796-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第796-1條，下列節錄的【空格】應填入何者？\n\n「土地所有人建築房屋逾越地界，鄰地所有人請求移去或變更時，法院得斟酌公共利益及當事人利益，免為全部或一部之移去或變更。但土地所有人【空格】逾越地界者，不適用之。」", "options": ["過失", "緊急避難", "正當防衛", "故意"], "answer": 3, "explanations": ["此處不是「過失」。民法第796-1條在本題位置規定的是「故意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「緊急避難」。民法第796-1條在本題位置規定的是「故意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「正當防衛」。民法第796-1條在本題位置規定的是「故意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第796-1條此處原文是「故意」。\n原句：土地所有人建築房屋逾越地界，鄰地所有人請求移去或變更時，法院得斟酌公共利益及當事人利益，免為全部或一部之移去或變更。但土地所有人故意逾越地界者，不適用之。"], "hint": "先判斷空格要填的是犯罪與責任，再核對條件與例外。", "sources": [{"title": "民法第796-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=796-1", "text": "土地所有人建築房屋逾越地界，鄰地所有人請求移去或變更時，法院得斟酌公共利益及當事人利益，免為全部或一部之移去或變更。但土地所有人故意逾越地界者，不適用之。\n前條第一項但書及第二項規定，於前項情形準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-819-1", "subject": "物權", "topic": "行政程序・§819", "kind": "法條", "question": "【法條原文辨識】依《民法》第819條，下列節錄的【空格】應填入何者？\n\n「各共有人，得自由【空格】其應有部分。」", "options": ["陳情", "處分", "契約", "指導"], "answer": 1, "explanations": ["此處不是「陳情」。民法第819條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第819條此處原文是「處分」。\n原句：各共有人，得自由處分其應有部分。", "此處不是「契約」。民法第819條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「指導」。民法第819條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第819條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=819", "text": "各共有人，得自由處分其應有部分。\n共有物之處分、變更、及設定負擔，應得共有人全體之同意。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-813-1", "subject": "物權", "topic": "物權種類・§813", "kind": "法條", "question": "【法條原文辨識】依《民法》第813條，下列節錄的【空格】應填入何者？\n\n「動產與他人之動產【空格】，不能識別，或識別需費過鉅者，準用前條之規定。」", "options": ["先占", "混合", "加工", "附合"], "answer": 1, "explanations": ["此處不是「先占」。民法第813條在本題位置規定的是「混合」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第813條此處原文是「混合」。\n原句：動產與他人之動產混合，不能識別，或識別需費過鉅者，準用前條之規定。", "此處不是「加工」。民法第813條在本題位置規定的是「混合」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「附合」。民法第813條在本題位置規定的是「混合」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第813條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=813", "text": "動產與他人之動產混合，不能識別，或識別需費過鉅者，準用前條之規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-786-2", "subject": "物權", "topic": "權利主體・§786", "kind": "法條", "question": "【法條原文辨識】依《民法》第786條，下列節錄的【空格】應填入何者？\n\n「依前項之規定，設置電線、水管、瓦斯管或其他管線後，如情事有變更時，他土地【空格】得請求變更其設置。」", "options": ["共有人", "承租人", "占有人", "所有人"], "answer": 3, "explanations": ["此處不是「共有人」。民法第786條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「承租人」。民法第786條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「占有人」。民法第786條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第786條此處原文是「所有人」。\n原句：依前項之規定，設置電線、水管、瓦斯管或其他管線後，如情事有變更時，他土地所有人得請求變更其設置。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第786條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=786", "text": "土地所有人非通過他人之土地，不能設置電線、水管、瓦斯管或其他管線，或雖能設置而需費過鉅者，得通過他人土地之上下而設置之。但應擇其損害最少之處所及方法為之，並應支付償金。\n依前項之規定，設置電線、水管、瓦斯管或其他管線後，如情事有變更時，他土地所有人得請求變更其設置。\n前項變更設置之費用，由土地所有人負擔。但法令另有規定或另有習慣者，從其規定或習慣。\n第七百七十九條第四項規定，於第一項但書之情形準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-881-14-1", "subject": "物權", "topic": "物權種類・§881-14", "kind": "法條", "question": "【法條原文辨識】依《民法》第881-14條，下列節錄的【空格】應填入何者？\n\n「最高限額【空格】所擔保之原債權確定後，除本節另有規定外，其擔保效力不及於繼續發生之債權或取得之票據上之權利。」", "options": ["所有權", "地上權", "抵押權", "典權"], "answer": 2, "explanations": ["此處不是「所有權」。民法第881-14條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「地上權」。民法第881-14條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第881-14條此處原文是「抵押權」。\n原句：最高限額抵押權所擔保之原債權確定後，除本節另有規定外，其擔保效力不及於繼續發生之債權或取得之票據上之權利。", "此處不是「典權」。民法第881-14條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第881-14條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=881-14", "text": "最高限額抵押權所擔保之原債權確定後，除本節另有規定外，其擔保效力不及於繼續發生之債權或取得之票據上之權利。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-918-1", "subject": "物權", "topic": "規範強度・§918", "kind": "法條", "question": "【法條原文辨識】依《民法》第918條，下列節錄的【空格】應填入何者？\n\n「出典人設定典權後，【空格】將典物讓與他人。但典權不因此而受影響。」", "options": ["無須", "不得", "得", "應"], "answer": 2, "explanations": ["此處不是「無須」。民法第918條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不得」。民法第918條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第918條此處原文是「得」。\n原句：出典人設定典權後，得將典物讓與他人。但典權不因此而受影響。", "此處不是「應」。民法第918條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是規範強度，再核對條件與例外。", "sources": [{"title": "民法第918條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=918", "text": "出典人設定典權後，得將典物讓與他人。但典權不因此而受影響。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-933-1", "subject": "物權", "topic": "物權種類・§933", "kind": "法條", "question": "【法條原文辨識】依《民法》第933條，下列節錄的【空格】應填入何者？\n\n「第八百八十八條至第八百九十條及第八百九十二條之規定，於【空格】準用之。」", "options": ["留置權", "質權", "抵押權", "不動產役權"], "answer": 0, "explanations": ["正確。民法第933條此處原文是「留置權」。\n原句：第八百八十八條至第八百九十條及第八百九十二條之規定，於留置權準用之。", "此處不是「質權」。民法第933條在本題位置規定的是「留置權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「抵押權」。民法第933條在本題位置規定的是「留置權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不動產役權」。民法第933條在本題位置規定的是「留置權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第933條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=933", "text": "第八百八十八條至第八百九十條及第八百九十二條之規定，於留置權準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-805-1", "subject": "物權", "topic": "期間・數額・比例・§805", "kind": "法條", "question": "【法條原文辨識】依《民法》第805條，下列節錄的【空格】應填入何者？\n\n「遺失物自通知或最後招領之日起【空格】內，有受領權之人認領時，拾得人、招領人、警察或自治機關，於通知、招領及保管之費用受償後，應將其物返還之。」", "options": ["二個月", "三個月", "六個月", "一個月"], "answer": 2, "explanations": ["此處不是「二個月」。民法第805條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三個月」。民法第805條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第805條此處原文是「六個月」。\n原句：遺失物自通知或最後招領之日起六個月內，有受領權之人認領時，拾得人、招領人、警察或自治機關，於通知、招領及保管之費用受償後，應將其物返還之。", "此處不是「一個月」。民法第805條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第805條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=805", "text": "遺失物自通知或最後招領之日起六個月內，有受領權之人認領時，拾得人、招領人、警察或自治機關，於通知、招領及保管之費用受償後，應將其物返還之。\n有受領權之人認領遺失物時，拾得人得請求報酬。但不得超過其物財產上價值十分之一；其不具有財產上價值者，拾得人亦得請求相當之報酬。\n有受領權人依前項規定給付報酬顯失公平者，得請求法院減少或免除其報酬。\n第二項報酬請求權，因六個月間不行使而消滅。\n第一項費用之支出者或得請求報酬之拾得人，在其費用或報酬未受清償前，就該遺失物有留置權；其權利人有數人時，遺失物占有人視為為全體權利人占有。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-759-1", "subject": "物權", "topic": "物權種類・§759", "kind": "法條", "question": "【法條原文辨識】依《民法》第759條，下列節錄的【空格】應填入何者？\n\n「因繼承、強制執行、徵收、法院之判決或其他非因法律行為，於登記前已取得【空格】物權者，應經登記，始得處分其物權。」", "options": ["債權", "有價證券", "不動產", "動產"], "answer": 2, "explanations": ["此處不是「債權」。民法第759條在本題位置規定的是「不動產」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「有價證券」。民法第759條在本題位置規定的是「不動產」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第759條此處原文是「不動產」。\n原句：因繼承、強制執行、徵收、法院之判決或其他非因法律行為，於登記前已取得不動產物權者，應經登記，始得處分其物權。", "此處不是「動產」。民法第759條在本題位置規定的是「不動產」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第759條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=759", "text": "因繼承、強制執行、徵收、法院之判決或其他非因法律行為，於登記前已取得不動產物權者，應經登記，始得處分其物權。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-917-1", "subject": "物權", "topic": "物權種類・§917", "kind": "法條", "question": "【法條原文辨識】依《民法》第917條，下列節錄的【空格】應填入何者？\n\n「典權人得將典權讓與他人或設定【空格】。」", "options": ["典權", "抵押權", "所有權", "地上權"], "answer": 1, "explanations": ["此處不是「典權」。民法第917條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第917條此處原文是「抵押權」。\n原句：典權人得將典權讓與他人或設定抵押權。", "此處不是「所有權」。民法第917條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「地上權」。民法第917條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第917條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=917", "text": "典權人得將典權讓與他人或設定抵押權。\n典物為土地，典權人在其上有建築物者，其典權與建築物，不得分離而為讓與或其他處分。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-900-1", "subject": "物權", "topic": "物權種類・§900", "kind": "法條", "question": "【法條原文辨識】依《民法》第900條，下列節錄的【空格】應填入何者？\n\n「稱權利質權者，謂以可讓與之【空格】或其他權利為標的物之質權。」", "options": ["動產", "有價證券", "債權", "不動產"], "answer": 2, "explanations": ["此處不是「動產」。民法第900條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「有價證券」。民法第900條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第900條此處原文是「債權」。\n原句：稱權利質權者，謂以可讓與之債權或其他權利為標的物之質權。", "此處不是「不動產」。民法第900條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第900條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=900", "text": "稱權利質權者，謂以可讓與之債權或其他權利為標的物之質權。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-881-6-1", "subject": "物權", "topic": "權利主體・§881-6", "kind": "法條", "question": "【法條原文辨識】依《民法》第881-6條，下列節錄的【空格】應填入何者？\n\n「最高限額抵押權所擔保之債權，於原債權確定前讓與他人者，其最高限額抵押權不隨同移轉。【空格】為債務人清償債務者，亦同。」", "options": ["第三人", "債務人", "受益人", "債權人"], "answer": 0, "explanations": ["正確。民法第881-6條此處原文是「第三人」。\n原句：最高限額抵押權所擔保之債權，於原債權確定前讓與他人者，其最高限額抵押權不隨同移轉。第三人為債務人清償債務者，亦同。", "此處不是「債務人」。民法第881-6條在本題位置規定的是「第三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受益人」。民法第881-6條在本題位置規定的是「第三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「債權人」。民法第881-6條在本題位置規定的是「第三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第881-6條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=881-6", "text": "最高限額抵押權所擔保之債權，於原債權確定前讓與他人者，其最高限額抵押權不隨同移轉。第三人為債務人清償債務者，亦同。\n最高限額抵押權所擔保之債權，於原債權確定前經第三人承擔其債務，而債務人免其責任者，抵押權人就該承擔之部分，不得行使最高限額抵押權。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-781-1", "subject": "物權", "topic": "權利主體・§781", "kind": "法條", "question": "【法條原文辨識】依《民法》第781條，下列節錄的【空格】應填入何者？\n\n「水源地、井、溝渠及其他水流地之【空格】得自由使用其水。但法令另有規定或另有習慣者，不在此限。」", "options": ["共有人", "所有人", "占有人", "承租人"], "answer": 1, "explanations": ["此處不是「共有人」。民法第781條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第781條此處原文是「所有人」。\n原句：水源地、井、溝渠及其他水流地之所有人得自由使用其水。但法令另有規定或另有習慣者，不在此限。", "此處不是「占有人」。民法第781條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「承租人」。民法第781條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第781條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=781", "text": "水源地、井、溝渠及其他水流地之所有人得自由使用其水。但法令另有規定或另有習慣者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-922-1-1", "subject": "物權", "topic": "物權種類・§922-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第922-1條，下列節錄的【空格】應填入何者？\n\n「因典物滅失受賠償而重建者，原【空格】對於重建之物，視為繼續存在。」", "options": ["所有權", "地上權", "抵押權", "典權"], "answer": 3, "explanations": ["此處不是「所有權」。民法第922-1條在本題位置規定的是「典權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「地上權」。民法第922-1條在本題位置規定的是「典權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「抵押權」。民法第922-1條在本題位置規定的是「典權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第922-1條此處原文是「典權」。\n原句：因典物滅失受賠償而重建者，原典權對於重建之物，視為繼續存在。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第922-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=922-1", "text": "因典物滅失受賠償而重建者，原典權對於重建之物，視為繼續存在。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-885-2", "subject": "物權", "topic": "權利主體・§885", "kind": "法條", "question": "【法條原文辨識】依《民法》第885條，下列節錄的【空格】應填入何者？\n\n「質權人不得使出質人或【空格】代自己占有質物。」", "options": ["債權人", "受益人", "債務人", "第三人"], "answer": 2, "explanations": ["此處不是「債權人」。民法第885條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受益人」。民法第885條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第885條此處原文是「債務人」。\n原句：質權人不得使出質人或債務人代自己占有質物。", "此處不是「第三人」。民法第885條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第885條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=885", "text": "質權之設定，因供擔保之動產移轉於債權人占有而生效力。\n質權人不得使出質人或債務人代自己占有質物。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-824-1-4", "subject": "物權", "topic": "憲政原則・§824-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第824-1條，下列節錄的【空格】應填入何者？\n\n「二、權利人已參加共有物分割【空格】。」", "options": ["訴願", "請願", "訴訟", "複決"], "answer": 2, "explanations": ["此處不是「訴願」。民法第824-1條在本題位置規定的是「訴訟」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「請願」。民法第824-1條在本題位置規定的是「訴訟」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第824-1條此處原文是「訴訟」。\n原句：二、權利人已參加共有物分割訴訟。", "此處不是「複決」。民法第824-1條在本題位置規定的是「訴訟」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第824-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=824-1", "text": "共有人自共有物分割之效力發生時起，取得分得部分之所有權。\n應有部分有抵押權或質權者，其權利不因共有物之分割而受影響。但有下列情形之一者，其權利移存於抵押人或出質人所分得之部分：\n一、權利人同意分割。\n二、權利人已參加共有物分割訴訟。\n三、權利人經共有人告知訴訟而未參加。\n前項但書情形，於以價金分配或以金錢補償者，準用第八百八十一條第一項、第二項或第八百九十九條第一項規定。\n前條第三項之情形，如為不動產分割者，應受補償之共有人，就其補償金額，對於補償義務人所分得之不動產，有抵押權。\n前項抵押權應於辦理共有物分割登記時，一併登記，其次序優先於第二項但書之抵押權。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-934-1", "subject": "物權", "topic": "物權種類・§934", "kind": "法條", "question": "【法條原文辨識】依《民法》第934條，下列節錄的【空格】應填入何者？\n\n「【空格】人因保管留置物所支出之必要費用，得向其物之所有人，請求償還。」", "options": ["不動產", "有價證券", "債權", "動產"], "answer": 2, "explanations": ["此處不是「不動產」。民法第934條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「有價證券」。民法第934條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第934條此處原文是「債權」。\n原句：債權人因保管留置物所支出之必要費用，得向其物之所有人，請求償還。", "此處不是「動產」。民法第934條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第934條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=934", "text": "債權人因保管留置物所支出之必要費用，得向其物之所有人，請求償還。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-828-3", "subject": "物權", "topic": "權利主體・§828", "kind": "法條", "question": "【法條原文辨識】依《民法》第828條，下列節錄的【空格】應填入何者？\n\n「公同共有物之處分及其他之權利行使，除法律另有規定外，應得公同【空格】全體之同意。」", "options": ["所有人", "占有人", "共有人", "承租人"], "answer": 2, "explanations": ["此處不是「所有人」。民法第828條在本題位置規定的是「共有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「占有人」。民法第828條在本題位置規定的是「共有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第828條此處原文是「共有人」。\n原句：公同共有物之處分及其他之權利行使，除法律另有規定外，應得公同共有人全體之同意。", "此處不是「承租人」。民法第828條在本題位置規定的是「共有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第828條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=828", "text": "公同共有人之權利義務，依其公同關係所由成立之法律、法律行為或習慣定之。\n第八百二十條、第八百二十一條及第八百二十六條之一規定，於公同共有準用之。\n公同共有物之處分及其他之權利行使，除法律另有規定外，應得公同共有人全體之同意。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-829-1", "subject": "物權", "topic": "權利主體・§829", "kind": "法條", "question": "【法條原文辨識】依《民法》第829條，下列節錄的【空格】應填入何者？\n\n「公同關係存續中，各公同【空格】，不得請求分割其公同共有物。」", "options": ["共有人", "所有人", "占有人", "承租人"], "answer": 0, "explanations": ["正確。民法第829條此處原文是「共有人」。\n原句：公同關係存續中，各公同共有人，不得請求分割其公同共有物。", "此處不是「所有人」。民法第829條在本題位置規定的是「共有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「占有人」。民法第829條在本題位置規定的是「共有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「承租人」。民法第829條在本題位置規定的是「共有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第829條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=829", "text": "公同關係存續中，各公同共有人，不得請求分割其公同共有物。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-906-1-1", "subject": "物權", "topic": "物權種類・§906-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第906-1條，下列節錄的【空格】應填入何者？\n\n「為質權標的物之債權，以不動產物權之設定或移轉為給付內容者，於其清償期屆至時，質權人得請求債務人將該不動產物權設定或移轉於出質人，並對該不動產物權有【空格】。」", "options": ["抵押權", "地上權", "所有權", "典權"], "answer": 0, "explanations": ["正確。民法第906-1條此處原文是「抵押權」。\n原句：為質權標的物之債權，以不動產物權之設定或移轉為給付內容者，於其清償期屆至時，質權人得請求債務人將該不動產物權設定或移轉於出質人，並對該不動產物權有抵押權。", "此處不是「地上權」。民法第906-1條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「所有權」。民法第906-1條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「典權」。民法第906-1條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第906-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=906-1", "text": "為質權標的物之債權，以不動產物權之設定或移轉為給付內容者，於其清償期屆至時，質權人得請求債務人將該不動產物權設定或移轉於出質人，並對該不動產物權有抵押權。\n前項抵押權應於不動產物權設定或移轉於出質人時，一併登記。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-826-1-3", "subject": "物權", "topic": "物權種類・§826-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第826-1條，下列節錄的【空格】應填入何者？\n\n「共有物應有部分讓與時，受讓人對讓與人就共有物因【空格】、管理或其他情形所生之負擔連帶負清償責任。」", "options": ["占有", "使用", "所有", "共有"], "answer": 1, "explanations": ["此處不是「占有」。民法第826-1條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第826-1條此處原文是「使用」。\n原句：共有物應有部分讓與時，受讓人對讓與人就共有物因使用、管理或其他情形所生之負擔連帶負清償責任。", "此處不是「所有」。民法第826-1條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「共有」。民法第826-1條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第826-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=826-1", "text": "不動產共有人間關於共有物使用、管理、分割或禁止分割之約定或依第八百二十條第一項規定所為之決定，於登記後，對於應有部分之受讓人或取得物權之人，具有效力。其由法院裁定所定之管理，經登記後，亦同。\n動產共有人間就共有物為前項之約定、決定或法院所為之裁定，對於應有部分之受讓人或取得物權之人，以受讓或取得時知悉其情事或可得而知者為限，亦具有效力。\n共有物應有部分讓與時，受讓人對讓與人就共有物因使用、管理或其他情形所生之負擔連帶負清償責任。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-920-2", "subject": "物權", "topic": "規範強度・§920", "kind": "法條", "question": "【法條原文辨識】依《民法》第920條，下列節錄的【空格】應填入何者？\n\n「前項情形，出典人就典物之餘存部分，為回贖時，【空格】由原典價扣除滅失部分之典價。其滅失部分之典價，依滅失時滅失部分之價值與滅失時典物之價值比例計算之。」", "options": ["得", "無須", "不得", "應"], "answer": 0, "explanations": ["正確。民法第920條此處原文是「得」。\n原句：前項情形，出典人就典物之餘存部分，為回贖時，得由原典價扣除滅失部分之典價。其滅失部分之典價，依滅失時滅失部分之價值與滅失時典物之價值比例計算之。", "此處不是「無須」。民法第920條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不得」。民法第920條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「應」。民法第920條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是規範強度，再核對條件與例外。", "sources": [{"title": "民法第920條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=920", "text": "典權存續中，典物因不可抗力致全部或一部滅失者，就其滅失之部分，典權與回贖權，均歸消滅。\n前項情形，出典人就典物之餘存部分，為回贖時，得由原典價扣除滅失部分之典價。其滅失部分之典價，依滅失時滅失部分之價值與滅失時典物之價值比例計算之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-769-1", "subject": "物權", "topic": "期間・數額・比例・§769", "kind": "法條", "question": "【法條原文辨識】依《民法》第769條，下列節錄的【空格】應填入何者？\n\n「以所有之意思，【空格】間和平、公然、繼續占有他人未登記之不動產者，得請求登記為所有人。」", "options": ["一年", "三年", "二十年", "二年"], "answer": 2, "explanations": ["此處不是「一年」。民法第769條在本題位置規定的是「二十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第769條在本題位置規定的是「二十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第769條此處原文是「二十年」。\n原句：以所有之意思，二十年間和平、公然、繼續占有他人未登記之不動產者，得請求登記為所有人。", "此處不是「二年」。民法第769條在本題位置規定的是「二十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第769條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=769", "text": "以所有之意思，二十年間和平、公然、繼續占有他人未登記之不動產者，得請求登記為所有人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-924-1-4", "subject": "物權", "topic": "法律要件・§924-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第924-1條，下列節錄的【空格】應填入何者？\n\n「一、典權人預示拒絕塗銷轉典權【空格】。」", "options": ["交付", "公證", "登記", "公告"], "answer": 2, "explanations": ["此處不是「交付」。民法第924-1條在本題位置規定的是「登記」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「公證」。民法第924-1條在本題位置規定的是「登記」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第924-1條此處原文是「登記」。\n原句：一、典權人預示拒絕塗銷轉典權登記。", "此處不是「公告」。民法第924-1條在本題位置規定的是「登記」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第924-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=924-1", "text": "經轉典之典物，出典人向典權人為回贖之意思表示時，典權人不於相當期間向轉典權人回贖並塗銷轉典權登記者，出典人得於原典價範圍內，以最後轉典價逕向最後轉典權人回贖典物。\n前項情形，轉典價低於原典價者，典權人或轉典權人得向出典人請求原典價與轉典價間之差額。出典人並得為各該請求權人提存其差額。\n前二項規定，於下列情形亦適用之：\n一、典權人預示拒絕塗銷轉典權登記。\n二、典權人行蹤不明或有其他情形致出典人不能為回贖之意思表示。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-924-1", "subject": "物權", "topic": "期間・數額・比例・§924", "kind": "法條", "question": "【法條原文辨識】依《民法》第924條，下列節錄的【空格】應填入何者？\n\n「典權未定期限者，出典人得隨時以原典價回贖典物。但自出典後經過【空格】不回贖者，典權人即取得典物所有權。」", "options": ["二年", "三年", "三十年", "一年"], "answer": 2, "explanations": ["此處不是「二年」。民法第924條在本題位置規定的是「三十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第924條在本題位置規定的是「三十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第924條此處原文是「三十年」。\n原句：典權未定期限者，出典人得隨時以原典價回贖典物。但自出典後經過三十年不回贖者，典權人即取得典物所有權。", "此處不是「一年」。民法第924條在本題位置規定的是「三十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第924條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=924", "text": "典權未定期限者，出典人得隨時以原典價回贖典物。但自出典後經過三十年不回贖者，典權人即取得典物所有權。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-841-3-1", "subject": "物權", "topic": "物權種類・§841-3", "kind": "法條", "question": "【法條原文辨識】依《民法》第841-3條，下列節錄的【空格】應填入何者？\n\n「法院依第八百四十條第四項定區分【空格】之期間，足以影響第三人之權利者，應併斟酌該第三人之利益。」", "options": ["抵押權", "典權", "所有權", "地上權"], "answer": 3, "explanations": ["此處不是「抵押權」。民法第841-3條在本題位置規定的是「地上權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「典權」。民法第841-3條在本題位置規定的是「地上權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「所有權」。民法第841-3條在本題位置規定的是「地上權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第841-3條此處原文是「地上權」。\n原句：法院依第八百四十條第四項定區分地上權之期間，足以影響第三人之權利者，應併斟酌該第三人之利益。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第841-3條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=841-3", "text": "法院依第八百四十條第四項定區分地上權之期間，足以影響第三人之權利者，應併斟酌該第三人之利益。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-950-1", "subject": "物權", "topic": "物權種類・§950", "kind": "法條", "question": "【法條原文辨識】依《民法》第950條，下列節錄的【空格】應填入何者？\n\n「盜贓、遺失物或其他非基於原占有人之意思而喪失其占有之物，如現占有人由公開交易場所，或由販賣與其物同種之物之商人，以【空格】買得者，非償還其支出之價金，不得回復其物。」", "options": ["故意", "重大過失", "惡意", "善意"], "answer": 3, "explanations": ["此處不是「故意」。民法第950條在本題位置規定的是「善意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「重大過失」。民法第950條在本題位置規定的是「善意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「惡意」。民法第950條在本題位置規定的是「善意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第950條此處原文是「善意」。\n原句：盜贓、遺失物或其他非基於原占有人之意思而喪失其占有之物，如現占有人由公開交易場所，或由販賣與其物同種之物之商人，以善意買得者，非償還其支出之價金，不得回復其物。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第950條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=950", "text": "盜贓、遺失物或其他非基於原占有人之意思而喪失其占有之物，如現占有人由公開交易場所，或由販賣與其物同種之物之商人，以善意買得者，非償還其支出之價金，不得回復其物。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-807-2", "subject": "物權", "topic": "期間・數額・比例・§807", "kind": "法條", "question": "【法條原文辨識】依《民法》第807條，下列節錄的【空格】應填入何者？\n\n「拾得人於受前項通知或公告後【空格】內未領取者，其物或賣得之價金歸屬於保管地之地方自治團體。」", "options": ["二個月", "三個月", "六個月", "一個月"], "answer": 1, "explanations": ["此處不是「二個月」。民法第807條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第807條此處原文是「三個月」。\n原句：拾得人於受前項通知或公告後三個月內未領取者，其物或賣得之價金歸屬於保管地之地方自治團體。", "此處不是「六個月」。民法第807條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第807條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第807條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=807", "text": "遺失物自通知或最後招領之日起逾六個月，未經有受領權之人認領者，由拾得人取得其所有權。警察或自治機關並應通知其領取遺失物或賣得之價金；其不能通知者，應公告之。\n拾得人於受前項通知或公告後三個月內未領取者，其物或賣得之價金歸屬於保管地之地方自治團體。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-875-1", "subject": "物權", "topic": "行政程序・§875", "kind": "法條", "question": "【法條原文辨識】依《民法》第875條，下列節錄的【空格】應填入何者？\n\n「為同一債權之擔保，於數不動產上設定抵押權，而未限定各個不動產所【空格】之金額者，抵押權人得就各個不動產賣得之價金，受債權全部或一部之清償。」", "options": ["負擔", "條件", "保留廢止權", "期限"], "answer": 0, "explanations": ["正確。民法第875條此處原文是「負擔」。\n原句：為同一債權之擔保，於數不動產上設定抵押權，而未限定各個不動產所負擔之金額者，抵押權人得就各個不動產賣得之價金，受債權全部或一部之清償。", "此處不是「條件」。民法第875條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「保留廢止權」。民法第875條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「期限」。民法第875條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第875條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=875", "text": "為同一債權之擔保，於數不動產上設定抵押權，而未限定各個不動產所負擔之金額者，抵押權人得就各個不動產賣得之價金，受債權全部或一部之清償。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-930-1", "subject": "物權", "topic": "權利主體・§930", "kind": "法條", "question": "【法條原文辨識】依《民法》第930條，下列節錄的【空格】應填入何者？\n\n「動產之留置，違反公共秩序或善良風俗者，不得為之。其與債權人應負擔之義務或與債權人【空格】間之約定相牴觸者，亦同。」", "options": ["第三人", "受益人", "債務人", "債權人"], "answer": 2, "explanations": ["此處不是「第三人」。民法第930條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受益人」。民法第930條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第930條此處原文是「債務人」。\n原句：動產之留置，違反公共秩序或善良風俗者，不得為之。其與債權人應負擔之義務或與債權人債務人間之約定相牴觸者，亦同。", "此處不是「債權人」。民法第930條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第930條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=930", "text": "動產之留置，違反公共秩序或善良風俗者，不得為之。其與債權人應負擔之義務或與債權人債務人間之約定相牴觸者，亦同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-862-1", "subject": "物權", "topic": "物權種類・§862", "kind": "法條", "question": "【法條原文辨識】依《民法》第862條，下列節錄的【空格】應填入何者？\n\n「【空格】之效力，及於抵押物之從物與從權利。」", "options": ["典權", "抵押權", "地上權", "所有權"], "answer": 1, "explanations": ["此處不是「典權」。民法第862條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第862條此處原文是「抵押權」。\n原句：抵押權之效力，及於抵押物之從物與從權利。", "此處不是「地上權」。民法第862條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「所有權」。民法第862條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第862條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=862", "text": "抵押權之效力，及於抵押物之從物與從權利。\n第三人於抵押權設定前，就從物取得之權利，不受前項規定之影響。\n以建築物為抵押者，其附加於該建築物而不具獨立性之部分，亦為抵押權效力所及。但其附加部分為獨立之物，如係於抵押權設定後附加者，準用第八百七十七條之規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-780-1", "subject": "物權", "topic": "物權種類・§780", "kind": "法條", "question": "【法條原文辨識】依《民法》第780條，下列節錄的【空格】應填入何者？\n\n「土地所有人因使其土地之水通過，得【空格】鄰地所有人所設置之工作物。但應按其受益之程度，負擔該工作物設置及保存之費用。」", "options": ["占有", "共有", "所有", "使用"], "answer": 3, "explanations": ["此處不是「占有」。民法第780條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「共有」。民法第780條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「所有」。民法第780條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第780條此處原文是「使用」。\n原句：土地所有人因使其土地之水通過，得使用鄰地所有人所設置之工作物。但應按其受益之程度，負擔該工作物設置及保存之費用。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第780條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=780", "text": "土地所有人因使其土地之水通過，得使用鄰地所有人所設置之工作物。但應按其受益之程度，負擔該工作物設置及保存之費用。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-867-1", "subject": "物權", "topic": "權利主體・§867", "kind": "法條", "question": "【法條原文辨識】依《民法》第867條，下列節錄的【空格】應填入何者？\n\n「不動產【空格】設定抵押權後，得將不動產讓與他人。但其抵押權不因此而受影響。」", "options": ["承租人", "共有人", "占有人", "所有人"], "answer": 3, "explanations": ["此處不是「承租人」。民法第867條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「共有人」。民法第867條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「占有人」。民法第867條在本題位置規定的是「所有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第867條此處原文是「所有人」。\n原句：不動產所有人設定抵押權後，得將不動產讓與他人。但其抵押權不因此而受影響。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第867條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=867", "text": "不動產所有人設定抵押權後，得將不動產讓與他人。但其抵押權不因此而受影響。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-852-1", "subject": "物權", "topic": "物權種類・§852", "kind": "法條", "question": "【法條原文辨識】依《民法》第852條，下列節錄的【空格】應填入何者？\n\n「【空格】因時效而取得者，以繼續並表見者為限。」", "options": ["抵押權", "質權", "留置權", "不動產役權"], "answer": 3, "explanations": ["此處不是「抵押權」。民法第852條在本題位置規定的是「不動產役權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「質權」。民法第852條在本題位置規定的是「不動產役權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「留置權」。民法第852條在本題位置規定的是「不動產役權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第852條此處原文是「不動產役權」。\n原句：不動產役權因時效而取得者，以繼續並表見者為限。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第852條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=852", "text": "不動產役權因時效而取得者，以繼續並表見者為限。\n前項情形，需役不動產為共有者，共有人中一人之行為，或對於共有人中一人之行為，為他共有人之利益，亦生效力。\n向行使不動產役權取得時效之各共有人為中斷時效之行為者，對全體共有人發生效力。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-875-3-1", "subject": "物權", "topic": "物權種類・§875-3", "kind": "法條", "question": "【法條原文辨識】依《民法》第875-3條，下列節錄的【空格】應填入何者？\n\n「為同一債權之擔保，於數不動產上設定【空格】者，在抵押物全部或部分同時拍賣，而其賣得價金超過所擔保之債權額時，經拍賣之各抵押物對債權分擔金額之計算，準用前條之規定。」", "options": ["地上權", "抵押權", "所有權", "典權"], "answer": 1, "explanations": ["此處不是「地上權」。民法第875-3條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第875-3條此處原文是「抵押權」。\n原句：為同一債權之擔保，於數不動產上設定抵押權者，在抵押物全部或部分同時拍賣，而其賣得價金超過所擔保之債權額時，經拍賣之各抵押物對債權分擔金額之計算，準用前條之規定。", "此處不是「所有權」。民法第875-3條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「典權」。民法第875-3條在本題位置規定的是「抵押權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第875-3條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=875-3", "text": "為同一債權之擔保，於數不動產上設定抵押權者，在抵押物全部或部分同時拍賣，而其賣得價金超過所擔保之債權額時，經拍賣之各抵押物對債權分擔金額之計算，準用前條之規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-826-2", "subject": "物權", "topic": "親屬與繼承・§826", "kind": "法條", "question": "【法條原文辨識】依《民法》第826條，下列節錄的【空格】應填入何者？\n\n「共有物分割後，關於共有物之證書，歸取得最大部分之人保存之。無取得最大部分者，由分割人協議定之。不能協議決定者，得聲請【空格】指定之。」", "options": ["戶政機關", "親屬會議", "法院", "檢察官"], "answer": 2, "explanations": ["此處不是「戶政機關」。民法第826條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「親屬會議」。民法第826條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第826條此處原文是「法院」。\n原句：共有物分割後，關於共有物之證書，歸取得最大部分之人保存之。無取得最大部分者，由分割人協議定之。不能協議決定者，得聲請法院指定之。", "此處不是「檢察官」。民法第826條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第826條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=826", "text": "共有物分割後，各分割人應保存其所得物之證書。\n共有物分割後，關於共有物之證書，歸取得最大部分之人保存之。無取得最大部分者，由分割人協議定之。不能協議決定者，得聲請法院指定之。\n各分割人，得請求使用他分割人所保存之證書。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-908-1", "subject": "物權", "topic": "法律要件・§908", "kind": "法條", "question": "【法條原文辨識】依《民法》第908條，下列節錄的【空格】應填入何者？\n\n「質權以未記載權利人之有價證券為標的物者，因【空格】其證券於質權人，而生設定質權之效力。以其他之有價證券為標的物者，並應依背書方法為之。」", "options": ["公告", "交付", "公證", "登記"], "answer": 1, "explanations": ["此處不是「公告」。民法第908條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第908條此處原文是「交付」。\n原句：質權以未記載權利人之有價證券為標的物者，因交付其證券於質權人，而生設定質權之效力。以其他之有價證券為標的物者，並應依背書方法為之。", "此處不是「公證」。民法第908條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「登記」。民法第908條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第908條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=908", "text": "質權以未記載權利人之有價證券為標的物者，因交付其證券於質權人，而生設定質權之效力。以其他之有價證券為標的物者，並應依背書方法為之。\n前項背書，得記載設定質權之意旨。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-881-4-1", "subject": "物權", "topic": "法律效果・§881-4", "kind": "法條", "question": "【法條原文辨識】依《民法》第881-4條，下列節錄的【空格】應填入何者？\n\n「最高限額抵押權得約定其所擔保原債權應確定之期日，並得於確定之期日前，約定【空格】之。」", "options": ["終止", "變更", "解除", "撤銷"], "answer": 1, "explanations": ["此處不是「終止」。民法第881-4條在本題位置規定的是「變更」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第881-4條此處原文是「變更」。\n原句：最高限額抵押權得約定其所擔保原債權應確定之期日，並得於確定之期日前，約定變更之。", "此處不是「解除」。民法第881-4條在本題位置規定的是「變更」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「撤銷」。民法第881-4條在本題位置規定的是「變更」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第881-4條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=881-4", "text": "最高限額抵押權得約定其所擔保原債權應確定之期日，並得於確定之期日前，約定變更之。\n前項確定之期日，自抵押權設定時起，不得逾三十年。逾三十年者，縮短為三十年。\n前項期限，當事人得更新之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-905-1", "subject": "物權", "topic": "權利主體・§905", "kind": "法條", "question": "【法條原文辨識】依《民法》第905條，下列節錄的【空格】應填入何者？\n\n「為質權標的物之債權，以金錢給付為內容，而其清償期先於其所擔保債權之清償期者，質權人得請求【空格】提存之，並對提存物行使其質權。」", "options": ["受益人", "第三人", "債權人", "債務人"], "answer": 3, "explanations": ["此處不是「受益人」。民法第905條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「第三人」。民法第905條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「債權人」。民法第905條在本題位置規定的是「債務人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第905條此處原文是「債務人」。\n原句：為質權標的物之債權，以金錢給付為內容，而其清償期先於其所擔保債權之清償期者，質權人得請求債務人提存之，並對提存物行使其質權。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第905條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=905", "text": "為質權標的物之債權，以金錢給付為內容，而其清償期先於其所擔保債權之清償期者，質權人得請求債務人提存之，並對提存物行使其質權。\n為質權標的物之債權，以金錢給付為內容，而其清償期後於其所擔保債權之清償期者，質權人於其清償期屆至時，得就擔保之債權額，為給付之請求。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-881-5-2", "subject": "物權", "topic": "期間・數額・比例・§881-5", "kind": "法條", "question": "【法條原文辨識】依《民法》第881-5條，下列節錄的【空格】應填入何者？\n\n「前項情形，除抵押人與抵押權人另有約定外，自請求之日起，經【空格】為其確定期日。」", "options": ["十五日", "五日", "七日", "三日"], "answer": 0, "explanations": ["正確。民法第881-5條此處原文是「十五日」。\n原句：前項情形，除抵押人與抵押權人另有約定外，自請求之日起，經十五日為其確定期日。", "此處不是「五日」。民法第881-5條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「七日」。民法第881-5條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三日」。民法第881-5條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第881-5條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=881-5", "text": "最高限額抵押權所擔保之原債權，未約定確定之期日者，抵押人或抵押權人得隨時請求確定其所擔保之原債權。\n前項情形，除抵押人與抵押權人另有約定外，自請求之日起，經十五日為其確定期日。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-789-1", "subject": "物權", "topic": "期間・數額・比例・§789", "kind": "法條", "question": "【法條原文辨識】依《民法》第789條，下列節錄的【空格】應填入何者？\n\n「因土地一部之讓與或分割，而與公路無適宜之聯絡，致不能為通常使用者，土地所有人因至公路，僅得通行受讓人或讓與人或他分割人之所有地。數宗土地同屬於【空格】所有，讓與其一部或同時分別讓與數人，而與公路無適宜之聯絡，致不能為通常使用者，亦同。」", "options": ["三人", "一人", "二人", "五人"], "answer": 1, "explanations": ["此處不是「三人」。民法第789條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第789條此處原文是「一人」。\n原句：因土地一部之讓與或分割，而與公路無適宜之聯絡，致不能為通常使用者，土地所有人因至公路，僅得通行受讓人或讓與人或他分割人之所有地。數宗土地同屬於一人所有，讓與其一部或同時分別讓與數人，而與公路無適宜之聯絡，致不能為通常使用者，亦同。", "此處不是「二人」。民法第789條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五人」。民法第789條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第789條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=789", "text": "因土地一部之讓與或分割，而與公路無適宜之聯絡，致不能為通常使用者，土地所有人因至公路，僅得通行受讓人或讓與人或他分割人之所有地。數宗土地同屬於一人所有，讓與其一部或同時分別讓與數人，而與公路無適宜之聯絡，致不能為通常使用者，亦同。\n前項情形，有通行權人，無須支付償金。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-964-1", "subject": "物權", "topic": "權利主體・§964", "kind": "法條", "question": "【法條原文辨識】依《民法》第964條，下列節錄的【空格】應填入何者？\n\n「占有，因【空格】喪失其對於物之事實上管領力而消滅。但其管領力僅一時不能實行者，不在此限。」", "options": ["所有人", "承租人", "占有人", "共有人"], "answer": 2, "explanations": ["此處不是「所有人」。民法第964條在本題位置規定的是「占有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「承租人」。民法第964條在本題位置規定的是「占有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第964條此處原文是「占有人」。\n原句：占有，因占有人喪失其對於物之事實上管領力而消滅。但其管領力僅一時不能實行者，不在此限。", "此處不是「共有人」。民法第964條在本題位置規定的是「占有人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第964條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=964", "text": "占有，因占有人喪失其對於物之事實上管領力而消滅。但其管領力僅一時不能實行者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-840-1", "subject": "物權", "topic": "期間・數額・比例・§840", "kind": "法條", "question": "【法條原文辨識】依《民法》第840條，下列節錄的【空格】應填入何者？\n\n「地上權人之工作物為建築物者，如地上權因存續期間屆滿而消滅，地上權人得於期間屆滿前，定【空格】以上之期間，請求土地所有人按該建築物之時價為補償。但契約另有約定者，從其約定。」", "options": ["二個月", "一個月", "三個月", "六個月"], "answer": 1, "explanations": ["此處不是「二個月」。民法第840條在本題位置規定的是「一個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第840條此處原文是「一個月」。\n原句：地上權人之工作物為建築物者，如地上權因存續期間屆滿而消滅，地上權人得於期間屆滿前，定一個月以上之期間，請求土地所有人按該建築物之時價為補償。但契約另有約定者，從其約定。", "此處不是「三個月」。民法第840條在本題位置規定的是「一個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「六個月」。民法第840條在本題位置規定的是「一個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第840條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=840", "text": "地上權人之工作物為建築物者，如地上權因存續期間屆滿而消滅，地上權人得於期間屆滿前，定一個月以上之期間，請求土地所有人按該建築物之時價為補償。但契約另有約定者，從其約定。\n土地所有人拒絕地上權人前項補償之請求或於期間內不為確答者，地上權之期間應酌量延長之。地上權人不願延長者，不得請求前項之補償。\n第一項之時價不能協議者，地上權人或土地所有人得聲請法院裁定之。土地所有人不願依裁定之時價補償者，適用前項規定。\n依第二項規定延長期間者，其期間由土地所有人與地上權人協議定之；不能協議者，得請求法院斟酌建築物與土地使用之利益，以判決定之。\n前項期間屆滿後，除經土地所有人與地上權人協議者外，不適用第一項及第二項規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-778-1", "subject": "物權", "topic": "行政程序・§778", "kind": "法條", "question": "【法條原文辨識】依《民法》第778條，下列節錄的【空格】應填入何者？\n\n「水流如因事變在鄰地阻塞，土地所有人得以自己之費用，為必要疏通之工事。但鄰地所有人受有利益者，應按其受益之程度，【空格】相當之費用。」", "options": ["條件", "期限", "保留廢止權", "負擔"], "answer": 3, "explanations": ["此處不是「條件」。民法第778條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「期限」。民法第778條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「保留廢止權」。民法第778條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第778條此處原文是「負擔」。\n原句：水流如因事變在鄰地阻塞，土地所有人得以自己之費用，為必要疏通之工事。但鄰地所有人受有利益者，應按其受益之程度，負擔相當之費用。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第778條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=778", "text": "水流如因事變在鄰地阻塞，土地所有人得以自己之費用，為必要疏通之工事。但鄰地所有人受有利益者，應按其受益之程度，負擔相當之費用。\n前項費用之負擔，另有習慣者，從其習慣。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-785-2", "subject": "物權", "topic": "行政程序・§785", "kind": "法條", "question": "【法條原文辨識】依《民法》第785條，下列節錄的【空格】應填入何者？\n\n「對岸地所有人於水流地之一部屬於其所有者，得使用前項之堰。但應按其受益之程度，【空格】該堰設置及保存之費用。」", "options": ["負擔", "條件", "保留廢止權", "期限"], "answer": 0, "explanations": ["正確。民法第785條此處原文是「負擔」。\n原句：對岸地所有人於水流地之一部屬於其所有者，得使用前項之堰。但應按其受益之程度，負擔該堰設置及保存之費用。", "此處不是「條件」。民法第785條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「保留廢止權」。民法第785條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「期限」。民法第785條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第785條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=785", "text": "水流地所有人有設堰之必要者，得使其堰附著於對岸。但對於因此所生之損害，應支付償金。\n對岸地所有人於水流地之一部屬於其所有者，得使用前項之堰。但應按其受益之程度，負擔該堰設置及保存之費用。\n前二項情形，法令另有規定或另有習慣者，從其規定或習慣。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-836-1", "subject": "物權", "topic": "期間・數額・比例・§836", "kind": "法條", "question": "【法條原文辨識】依《民法》第836條，下列節錄的【空格】應填入何者？\n\n「地上權人積欠地租達【空格】之總額，除另有習慣外，土地所有人得定相當期限催告地上權人支付地租，如地上權人於期限內不為支付，土地所有人得終止地上權。地上權經設定抵押權者，並應同時將該催告之事實通知抵押權人。」", "options": ["五年", "一年", "三年", "二年"], "answer": 3, "explanations": ["此處不是「五年」。民法第836條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一年」。民法第836條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第836條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第836條此處原文是「二年」。\n原句：地上權人積欠地租達二年之總額，除另有習慣外，土地所有人得定相當期限催告地上權人支付地租，如地上權人於期限內不為支付，土地所有人得終止地上權。地上權經設定抵押權者，並應同時將該催告之事實通知抵押權人。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第836條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=836", "text": "地上權人積欠地租達二年之總額，除另有習慣外，土地所有人得定相當期限催告地上權人支付地租，如地上權人於期限內不為支付，土地所有人得終止地上權。地上權經設定抵押權者，並應同時將該催告之事實通知抵押權人。\n地租之約定經登記者，地上權讓與時，前地上權人積欠之地租應併同計算。受讓人就前地上權人積欠之地租，應與讓與人連帶負清償責任。\n第一項終止，應向地上權人以意思表示為之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-902-1", "subject": "物權", "topic": "物權種類・§902", "kind": "法條", "question": "【法條原文辨識】依《民法》第902條，下列節錄的【空格】應填入何者？\n\n「權利【空格】之設定，除依本節規定外，並應依關於其權利讓與之規定為之。」", "options": ["留置權", "抵押權", "不動產役權", "質權"], "answer": 3, "explanations": ["此處不是「留置權」。民法第902條在本題位置規定的是「質權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「抵押權」。民法第902條在本題位置規定的是「質權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不動產役權」。民法第902條在本題位置規定的是「質權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第902條此處原文是「質權」。\n原句：權利質權之設定，除依本節規定外，並應依關於其權利讓與之規定為之。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第902條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=902", "text": "權利質權之設定，除依本節規定外，並應依關於其權利讓與之規定為之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-807-1-3", "subject": "物權", "topic": "期間・數額・比例・§807-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第807-1條，下列節錄的【空格】應填入何者？\n\n「一、自通知或招領之日起逾【空格】。」", "options": ["五日", "三日", "七日", "十五日"], "answer": 3, "explanations": ["此處不是「五日」。民法第807-1條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三日」。民法第807-1條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「七日」。民法第807-1條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第807-1條此處原文是「十五日」。\n原句：一、自通知或招領之日起逾十五日。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第807-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=807-1", "text": "遺失物價值在新臺幣五百元以下者，拾得人應從速通知遺失人、所有人或其他有受領權之人。其有第八百零三條第一項但書之情形者，亦得依該條第一項但書及第二項規定辦理。\n前項遺失物於下列期間未經有受領權之人認領者，由拾得人取得其所有權或變賣之價金：\n一、自通知或招領之日起逾十五日。\n二、不能依前項規定辦理，自拾得日起逾一個月。\n第八百零五條至前條規定，於前二項情形準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1127-1", "subject": "親屬法", "topic": "規範強度・§1127", "kind": "法條", "question": "【法條原文辨識】依《民法》第1127條，下列節錄的【空格】應填入何者？\n\n「家屬已成年者，【空格】請求由家分離。」", "options": ["無須", "應", "得", "不得"], "answer": 2, "explanations": ["此處不是「無須」。民法第1127條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「應」。民法第1127條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1127條此處原文是「得」。\n原句：家屬已成年者，得請求由家分離。", "此處不是「不得」。民法第1127條在本題位置規定的是「得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是規範強度，再核對條件與例外。", "sources": [{"title": "民法第1127條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1127", "text": "家屬已成年者，得請求由家分離。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-975-1", "subject": "親屬法", "topic": "親屬與繼承・§975", "kind": "法條", "question": "【法條原文辨識】依《民法》第975條，下列節錄的【空格】應填入何者？\n\n「【空格】，不得請求強迫履行。」", "options": ["婚約", "收養", "離婚", "結婚"], "answer": 0, "explanations": ["正確。民法第975條此處原文是「婚約」。\n原句：婚約，不得請求強迫履行。", "此處不是「收養」。民法第975條在本題位置規定的是「婚約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「離婚」。民法第975條在本題位置規定的是「婚約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「結婚」。民法第975條在本題位置規定的是「婚約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第975條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=975", "text": "婚約，不得請求強迫履行。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1034-1", "subject": "親屬法", "topic": "親屬與繼承・§1034", "kind": "法條", "question": "【法條原文辨識】依《民法》第1034條，下列節錄的【空格】應填入何者？\n\n「夫或妻【空格】前或婚姻關係存續中所負之債務，應由共同財產，並各就其特有財產負清償責任。」", "options": ["婚約", "離婚", "結婚", "收養"], "answer": 2, "explanations": ["此處不是「婚約」。民法第1034條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「離婚」。民法第1034條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1034條此處原文是「結婚」。\n原句：夫或妻結婚前或婚姻關係存續中所負之債務，應由共同財產，並各就其特有財產負清償責任。", "此處不是「收養」。民法第1034條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1034條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1034", "text": "夫或妻結婚前或婚姻關係存續中所負之債務，應由共同財產，並各就其特有財產負清償責任。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1113-6-3", "subject": "親屬法", "topic": "期間・數額・比例・§1113-6", "kind": "法條", "question": "【法條原文辨識】依《民法》第1113-6條，下列節錄的【空格】應填入何者？\n\n「法院為監護之宣告後，前二項所定執行職務之監護人中之【空格】或數人有第一千一百零六條第一項之情形者，由其他監護人執行職務。」", "options": ["二人", "五人", "三人", "一人"], "answer": 3, "explanations": ["此處不是「二人」。民法第1113-6條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五人」。民法第1113-6條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三人」。民法第1113-6條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1113-6條此處原文是「一人」。\n原句：法院為監護之宣告後，前二項所定執行職務之監護人中之一人或數人有第一千一百零六條第一項之情形者，由其他監護人執行職務。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1113-6條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1113-6", "text": "法院為監護之宣告後，監護人共同執行職務時，監護人全體有第一千一百零六條第一項或第一千一百零六條之一第一項之情形者，法院得依第十四條第一項所定聲請權人之聲請或依職權，就第一千一百十一條第一項所列之人另行選定或改定為監護人。\n法院為監護之宣告後，意定監護契約約定監護人數人分別執行職務時，執行同一職務之監護人全體有第一千一百零六條第一項或第一千一百零六條之一第一項之情形者，法院得依前項規定另行選定或改定全體監護人。但執行其他職務之監護人無不適任之情形者，法院應優先選定或改定其為監護人。\n法院為監護之宣告後，前二項所定執行職務之監護人中之一人或數人有第一千一百零六條第一項之情形者，由其他監護人執行職務。\n法院為監護之宣告後，第一項及第二項所定執行職務之監護人中之一人或數人有第一千一百零六條之一第一項之情形者，法院得依第十四條第一項所定聲請權人之聲請或依職權解任之，由其他監護人執行職務。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1088-1", "subject": "親屬法", "topic": "親屬與繼承・§1088", "kind": "法條", "question": "【法條原文辨識】依《民法》第1088條，下列節錄的【空格】應填入何者？\n\n「未成年子女之特有財產，由【空格】共同管理。」", "options": ["祖父母", "兄弟姊妹", "直系血親卑親屬", "父母"], "answer": 3, "explanations": ["此處不是「祖父母」。民法第1088條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「兄弟姊妹」。民法第1088條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「直系血親卑親屬」。民法第1088條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1088條此處原文是「父母」。\n原句：未成年子女之特有財產，由父母共同管理。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1088條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1088", "text": "未成年子女之特有財產，由父母共同管理。\n父母對於未成年子女之特有財產，有使用、收益之權。但非為子女之利益，不得處分之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-971-1", "subject": "親屬法", "topic": "親屬與繼承・§971", "kind": "法條", "question": "【法條原文辨識】依《民法》第971條，下列節錄的【空格】應填入何者？\n\n「姻親關係，因離婚而消滅；【空格】經撤銷者亦同。」", "options": ["婚約", "離婚", "收養", "結婚"], "answer": 3, "explanations": ["此處不是「婚約」。民法第971條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「離婚」。民法第971條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「收養」。民法第971條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第971條此處原文是「結婚」。\n原句：姻親關係，因離婚而消滅；結婚經撤銷者亦同。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第971條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=971", "text": "姻親關係，因離婚而消滅；結婚經撤銷者亦同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1087-1", "subject": "親屬法", "topic": "法律要件・§1087", "kind": "法條", "question": "【法條原文辨識】依《民法》第1087條，下列節錄的【空格】應填入何者？\n\n「未成年子女，因繼承、贈與或其他【空格】取得之財產，為其特有財產。」", "options": ["無償", "附期限", "有償", "附條件"], "answer": 0, "explanations": ["正確。民法第1087條此處原文是「無償」。\n原句：未成年子女，因繼承、贈與或其他無償取得之財產，為其特有財產。", "此處不是「附期限」。民法第1087條在本題位置規定的是「無償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「有償」。民法第1087條在本題位置規定的是「無償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「附條件」。民法第1087條在本題位置規定的是「無償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1087條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1087", "text": "未成年子女，因繼承、贈與或其他無償取得之財產，為其特有財產。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-988-4", "subject": "親屬法", "topic": "物權種類・§988", "kind": "法條", "question": "【法條原文辨識】依《民法》第988條，下列節錄的【空格】應填入何者？\n\n「三、違反第九百八十五條規定。但重婚之雙方當事人因【空格】且無過失信賴一方前婚姻消滅之兩願離婚登記或離婚確定判決而結婚者，不在此限。」", "options": ["重大過失", "惡意", "故意", "善意"], "answer": 3, "explanations": ["此處不是「重大過失」。民法第988條在本題位置規定的是「善意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「惡意」。民法第988條在本題位置規定的是「善意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「故意」。民法第988條在本題位置規定的是「善意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第988條此處原文是「善意」。\n原句：三、違反第九百八十五條規定。但重婚之雙方當事人因善意且無過失信賴一方前婚姻消滅之兩願離婚登記或離婚確定判決而結婚者，不在此限。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第988條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=988", "text": "結婚有下列情形之一者，無效：\n一、不具備第九百八十二條之方式。\n二、違反第九百八十三條規定。\n三、違反第九百八十五條規定。但重婚之雙方當事人因善意且無過失信賴一方前婚姻消滅之兩願離婚登記或離婚確定判決而結婚者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1125-1", "subject": "親屬法", "topic": "行政程序・§1125", "kind": "法條", "question": "【法條原文辨識】依《民法》第1125條，下列節錄的【空格】應填入何者？\n\n「家務由家長管理。但家長得以家務之一部，【空格】家屬處理。」", "options": ["委辦", "代理", "委任", "委託"], "answer": 3, "explanations": ["此處不是「委辦」。民法第1125條在本題位置規定的是「委託」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「代理」。民法第1125條在本題位置規定的是「委託」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「委任」。民法第1125條在本題位置規定的是「委託」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1125條此處原文是「委託」。\n原句：家務由家長管理。但家長得以家務之一部，委託家屬處理。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1125條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1125", "text": "家務由家長管理。但家長得以家務之一部，委託家屬處理。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1107-3", "subject": "親屬法", "topic": "期間・數額・比例・§1107", "kind": "法條", "question": "【法條原文辨識】依《民法》第1107條，下列節錄的【空格】應填入何者？\n\n「前二項情形，原監護人應於監護關係終止時起【空格】內，為受監護人財產之結算，作成結算書，送交新監護人、受監護人或其繼承人。」", "options": ["六個月", "一個月", "二個月", "三個月"], "answer": 2, "explanations": ["此處不是「六個月」。民法第1107條在本題位置規定的是「二個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1107條在本題位置規定的是「二個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1107條此處原文是「二個月」。\n原句：前二項情形，原監護人應於監護關係終止時起二個月內，為受監護人財產之結算，作成結算書，送交新監護人、受監護人或其繼承人。", "此處不是「三個月」。民法第1107條在本題位置規定的是「二個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1107條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1107", "text": "監護人變更時，原監護人應即將受監護人之財產移交於新監護人。\n受監護之原因消滅時，原監護人應即將受監護人之財產交還於受監護人；如受監護人死亡時，交還於其繼承人。\n前二項情形，原監護人應於監護關係終止時起二個月內，為受監護人財產之結算，作成結算書，送交新監護人、受監護人或其繼承人。\n新監護人、受監護人或其繼承人對於前項結算書未為承認前，原監護人不得免其責任。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1093-2", "subject": "親屬法", "topic": "期間・數額・比例・§1093", "kind": "法條", "question": "【法條原文辨識】依《民法》第1093條，下列節錄的【空格】應填入何者？\n\n「前項遺囑指定之監護人，應於知悉其為監護人後【空格】內，將姓名、住所報告法院；其遺囑未指定會同開具財產清冊之人者，並應申請當地直轄市、縣（市）政府指派人員會同開具財產清冊。」", "options": ["七日", "三日", "五日", "十五日"], "answer": 3, "explanations": ["此處不是「七日」。民法第1093條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三日」。民法第1093條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五日」。民法第1093條在本題位置規定的是「十五日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1093條此處原文是「十五日」。\n原句：前項遺囑指定之監護人，應於知悉其為監護人後十五日內，將姓名、住所報告法院；其遺囑未指定會同開具財產清冊之人者，並應申請當地直轄市、縣（市）政府指派人員會同開具財產清冊。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1093條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1093", "text": "最後行使、負擔對於未成年子女之權利、義務之父或母，得以遺囑指定監護人。\n前項遺囑指定之監護人，應於知悉其為監護人後十五日內，將姓名、住所報告法院；其遺囑未指定會同開具財產清冊之人者，並應申請當地直轄市、縣（市）政府指派人員會同開具財產清冊。\n於前項期限內，監護人未向法院報告者，視為拒絕就職。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1124-1", "subject": "親屬法", "topic": "期間・數額・比例・§1124", "kind": "法條", "question": "【法條原文辨識】依《民法》第1124條，下列節錄的【空格】應填入何者？\n\n「家長由親屬團體中推定之；無推定時，以家中之最尊輩者為之；尊輩同者，以年長者為之；最尊或最長者不能或不願管理家務時，由其指定家屬【空格】代理之。」", "options": ["五人", "三人", "二人", "一人"], "answer": 3, "explanations": ["此處不是「五人」。民法第1124條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三人」。民法第1124條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二人」。民法第1124條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1124條此處原文是「一人」。\n原句：家長由親屬團體中推定之；無推定時，以家中之最尊輩者為之；尊輩同者，以年長者為之；最尊或最長者不能或不願管理家務時，由其指定家屬一人代理之。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1124條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1124", "text": "家長由親屬團體中推定之；無推定時，以家中之最尊輩者為之；尊輩同者，以年長者為之；最尊或最長者不能或不願管理家務時，由其指定家屬一人代理之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-980-1", "subject": "親屬法", "topic": "期間・數額・比例・§980", "kind": "法條", "question": "【法條原文辨識】依《民法》第980條，下列節錄的【空格】應填入何者？\n\n「男女未滿【空格】者，不得結婚。」", "options": ["十四歲", "十六歲", "十八歲", "七歲"], "answer": 2, "explanations": ["此處不是「十四歲」。民法第980條在本題位置規定的是「十八歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「十六歲」。民法第980條在本題位置規定的是「十八歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第980條此處原文是「十八歲」。\n原句：男女未滿十八歲者，不得結婚。", "此處不是「七歲」。民法第980條在本題位置規定的是「十八歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第980條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=980", "text": "男女未滿十八歲者，不得結婚。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1033-1", "subject": "親屬法", "topic": "行政程序・§1033", "kind": "法條", "question": "【法條原文辨識】依《民法》第1033條，下列節錄的【空格】應填入何者？\n\n「夫妻之一方，對於共同財產為【空格】時，應得他方之同意。」", "options": ["陳情", "契約", "處分", "指導"], "answer": 2, "explanations": ["此處不是「陳情」。民法第1033條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「契約」。民法第1033條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1033條此處原文是「處分」。\n原句：夫妻之一方，對於共同財產為處分時，應得他方之同意。", "此處不是「指導」。民法第1033條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1033條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1033", "text": "夫妻之一方，對於共同財產為處分時，應得他方之同意。\n前項同意之欠缺，不得對抗第三人。但第三人已知或可得而知其欠缺，或依情形，可認為該財產屬於共同財產者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1041-4", "subject": "親屬法", "topic": "親屬與繼承・§1041", "kind": "法條", "question": "【法條原文辨識】依《民法》第1041條，下列節錄的【空格】應填入何者？\n\n「夫或妻勞力所得以外之財產，適用關於【空格】之規定。」", "options": ["分別財產制", "法定財產制", "共同財產制", "剩餘財產分配制"], "answer": 0, "explanations": ["正確。民法第1041條此處原文是「分別財產制」。\n原句：夫或妻勞力所得以外之財產，適用關於分別財產制之規定。", "此處不是「法定財產制」。民法第1041條在本題位置規定的是「分別財產制」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「共同財產制」。民法第1041條在本題位置規定的是「分別財產制」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「剩餘財產分配制」。民法第1041條在本題位置規定的是「分別財產制」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1041條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1041", "text": "夫妻得以契約訂定僅以勞力所得為限為共同財產。\n前項勞力所得，指夫或妻於婚姻關係存續中取得之薪資、工資、紅利、獎金及其他與勞力所得有關之財產收入。勞力所得之孳息及代替利益，亦同。\n不能證明為勞力所得或勞力所得以外財產者，推定為勞力所得。\n夫或妻勞力所得以外之財產，適用關於分別財產制之規定。\n第一千零三十四條、第一千零三十八條及第一千零四十條之規定，於第一項情形準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1060-1", "subject": "親屬法", "topic": "親屬與繼承・§1060", "kind": "法條", "question": "【法條原文辨識】依《民法》第1060條，下列節錄的【空格】應填入何者？\n\n「未成年之子女，以其【空格】之住所為住所。」", "options": ["祖父母", "兄弟姊妹", "父母", "直系血親卑親屬"], "answer": 2, "explanations": ["此處不是「祖父母」。民法第1060條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「兄弟姊妹」。民法第1060條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1060條此處原文是「父母」。\n原句：未成年之子女，以其父母之住所為住所。", "此處不是「直系血親卑親屬」。民法第1060條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1060條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1060", "text": "未成年之子女，以其父母之住所為住所。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-979-2-1", "subject": "親屬法", "topic": "期間・數額・比例・§979-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第979-2條，下列節錄的【空格】應填入何者？\n\n「第九百七十七條至第九百七十九條之一所規定之請求權，因【空格】間不行使而消滅。」", "options": ["五年", "二年", "一年", "三年"], "answer": 1, "explanations": ["此處不是「五年」。民法第979-2條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第979-2條此處原文是「二年」。\n原句：第九百七十七條至第九百七十九條之一所規定之請求權，因二年間不行使而消滅。", "此處不是「一年」。民法第979-2條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第979-2條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第979-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=979-2", "text": "第九百七十七條至第九百七十九條之一所規定之請求權，因二年間不行使而消滅。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1102-1", "subject": "親屬法", "topic": "規範強度・§1102", "kind": "法條", "question": "【法條原文辨識】依《民法》第1102條，下列節錄的【空格】應填入何者？\n\n「監護人【空格】受讓受監護人之財產。」", "options": ["不得", "應", "得", "無須"], "answer": 0, "explanations": ["正確。民法第1102條此處原文是「不得」。\n原句：監護人不得受讓受監護人之財產。", "此處不是「應」。民法第1102條在本題位置規定的是「不得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「得」。民法第1102條在本題位置規定的是「不得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「無須」。民法第1102條在本題位置規定的是「不得」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是規範強度，再核對條件與例外。", "sources": [{"title": "民法第1102條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1102", "text": "監護人不得受讓受監護人之財產。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1018-1-1", "subject": "親屬法", "topic": "憲政原則・§1018-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1018-1條，下列節錄的【空格】應填入何者？\n\n「夫妻於家庭生活費用外，得協議一定數額之金錢，供夫或妻【空格】處分。」", "options": ["資格", "責任", "義務", "自由"], "answer": 3, "explanations": ["此處不是「資格」。民法第1018-1條在本題位置規定的是「自由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「責任」。民法第1018-1條在本題位置規定的是「自由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「義務」。民法第1018-1條在本題位置規定的是「自由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1018-1條此處原文是「自由」。\n原句：夫妻於家庭生活費用外，得協議一定數額之金錢，供夫或妻自由處分。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1018-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1018-1", "text": "夫妻於家庭生活費用外，得協議一定數額之金錢，供夫或妻自由處分。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}]);
